 public static string UpdateSockets(){var data=JObject.Parse(File.ReadAllText(Root+"/Source/weapons.json"));int count=0;foreach(var source in data["weapons"]){string id=(string)source["definition"]["id"];var def=AssetDatabase.LoadAssetAtPath<PortWeaponDefinition>(Definitions+"/"+id+".asset");var cfg=source["cfg"];def.rightPose=(string)cfg["rightPose"];def.leftPose=(string)cfg["leftPose"];var rotation=cfg["hip"]?["r"];if(rotation!=null)def.hipRotation=Quaternion.AngleAxis(-(float)rotation[0]*Mathf.Rad2Deg,Vector3.right)*Quaternion.AngleAxis(-(float)rotation[1]*Mathf.Rad2Deg,Vector3.up)*Quaternion.AngleAxis((float)rotation[2]*Mathf.Rad2Deg,Vector3.forward);var motions=new List<PortWeaponMotion>();if(cfg["shot"]!=null)foreach(var motion in cfg["shot"]){var m=new PortWeaponMotion();m.part=(string)motion["part"];if(motion["p"]!=null)m.position=V(motion["p"]);if(motion["r"]!=null){var r=motion["r"];m.rotation=new Vector3(-(float)r[0],-(float)r[1],(float)r[2])*Mathf.Rad2Deg;}m.duration=(float?)motion["dur"]??.09f;motions.Add(m);}def.shotMotions=motions.ToArray();var sockets=source["sockets"];if(sockets["rightHand"]!=null){def.rightGrip=V(sockets["rightHand"]["p"]);def.rightRotation=Q(sockets["rightHand"]["q"]);}if(sockets["leftHand"]!=null){def.leftGrip=V(sockets["leftHand"]["p"]);def.leftRotation=Q(sockets["leftHand"]["q"]);}EditorUtility.SetDirty(def);count++;}AssetDatabase.SaveAssets();return "Updated "+count+" grip frames";}
 public static string Import(){var data=JObject.Parse(File.ReadAllText(Root+"/Source/weapons.json"));foreach(var d in new[]{Root+"/Meshes",Root+"/Materials",Root+"/Prefabs",Definitions})Directory.CreateDirectory(d);AssetDatabase.Refresh();var materials=new List<Material>();int index=0;
 foreach(var source in data["materials"]){string path=Root+"/Materials/Weapon_"+index+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find("FalloutPort/VaultSurface"));AssetDatabase.CreateAsset(mat,path);}var c=source["color"];mat.SetColor("_BaseColor",new Color((float)c[0],(float)c[1],(float)c[2]));c=source["emission"];mat.SetColor("_Emission",new Color((float)c[0],(float)c[1],(float)c[2]));mat.SetFloat("_VertexColor",(bool)source["vertexColors"]?1:0);int tx=(int)source["texture"];if(tx>=0)mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"/Source/texture_"+tx+".png"));EditorUtility.SetDirty(mat);materials.Add(mat);index++;}
 int count=0;foreach(var source in data["weapons"]){string id=(string)source["definition"]["id"];var nodes=new List<GameObject>();int triangles=0;foreach(var node in source["nodes"]){var obj=new GameObject((string)node["name"]);obj.layer=2;int parent=(int)node["parent"];if(parent>=0)obj.transform.SetParent(nodes[parent].transform,false);obj.transform.localPosition=V(node["p"]);obj.transform.localRotation=Q(node["q"]);var scale=node["s"];obj.transform.localScale=new Vector3((float)scale[0],(float)scale[1],(float)scale[2]);nodes.Add(obj);if(node["vertices"]==null)continue;var vertices=node["vertices"].ToObject<float[]>();var normals=node["normals"].ToObject<float[]>();var uv=node["uv"].ToObject<float[]>();var colors=node["colors"].ToObject<float[]>();var indices=node["indices"].ToObject<int[]>();var vs=new Vector3[vertices.Length/3];var ns=new Vector3[vs.Length];var uvs=new Vector2[vs.Length];var cs=new Color[vs.Length];for(int i=0;i<vs.Length;i++){vs[i]=new Vector3(vertices[3*i],vertices[3*i+1],-vertices[3*i+2]);if(normals.Length>3*i+2)ns[i]=new Vector3(normals[3*i],normals[3*i+1],-normals[3*i+2]);if(uv.Length>2*i+1)uvs[i]=new Vector2(uv[2*i],uv[2*i+1]);cs[i]=colors.Length>3*i+2?new Color(colors[3*i],colors[3*i+1],colors[3*i+2]):Color.white;}for(int i=0;i<indices.Length;i+=3){int t=indices[i+1];indices[i+1]=indices[i+2];indices[i+2]=t;}string path=Root+"/Meshes/"+id+"_"+nodes.Count+".asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(!mesh){mesh=new Mesh();AssetDatabase.CreateAsset(mesh,path);}mesh.Clear();mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.vertices=vs;mesh.normals=ns;mesh.uv=uvs;mesh.colors=cs;mesh.triangles=indices;mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);triangles+=indices.Length/3;obj.AddComponent<MeshFilter>().sharedMesh=mesh;obj.AddComponent<MeshRenderer>().sharedMaterial=materials[(int)node["material"]];}
 var root=nodes[0];root.name=id;string prefabPath=Root+"/Prefabs/"+id+".prefab";var prefab=PrefabUtility.SaveAsPrefabAsset(root,prefabPath);UnityEngine.Object.DestroyImmediate(root);string defPath=Definitions+"/"+id+".asset";var def=AssetDatabase.LoadAssetAtPath<PortWeaponDefinition>(defPath);if(!def){def=ScriptableObject.CreateInstance<PortWeaponDefinition>();AssetDatabase.CreateAsset(def,defPath);}var original=source["definition"];def.id=id;def.displayName=(string)original["name"];def.description=(string)original["desc"];def.unique=(bool)original["unique"];def.weight=(float)original["weight"];def.value=(int)original["value"];def.stats=JsonUtility.FromJson<PortWeaponStats>(original["weapon"].ToString());def.prefab=prefab;var cfg=source["cfg"];def.rightPose=(string)cfg["rightPose"];def.leftPose=(string)cfg["leftPose"];var rotation=cfg["hip"]?["r"];if(rotation!=null)def.hipRotation=Quaternion.AngleAxis(-(float)rotation[0]*Mathf.Rad2Deg,Vector3.right)*Quaternion.AngleAxis(-(float)rotation[1]*Mathf.Rad2Deg,Vector3.up)*Quaternion.AngleAxis((float)rotation[2]*Mathf.Rad2Deg,Vector3.forward);var motions=new List<PortWeaponMotion>();if(cfg["shot"]!=null)foreach(var motion in cfg["shot"]){var m=new PortWeaponMotion();m.part=(string)motion["part"];if(motion["p"]!=null)m.position=V(motion["p"]);if(motion["r"]!=null){var r=motion["r"];m.rotation=new Vector3(-(float)r[0],-(float)r[1],(float)r[2])*Mathf.Rad2Deg;}m.duration=(float?)motion["dur"]??.09f;motions.Add(m);}def.shotMotions=motions.ToArray();var sockets=source["sockets"];if(sockets["muzzle"]!=null)def.muzzle=V(sockets["muzzle"]["p"]);if(sockets["sight"]!=null)def.sight=V(sockets["sight"]["p"]);if(sockets["rightHand"]!=null){def.rightGrip=V(sockets["rightHand"]["p"]);def.rightRotation=Q(sockets["rightHand"]["q"]);}def.hasLeftGrip=sockets["leftHand"]!=null;if(def.hasLeftGrip){def.leftGrip=V(sockets["leftHand"]["p"]);def.leftRotation=Q(sockets["leftHand"]["q"]);}def.oneHanded=(bool?)source["cfg"]["oneHanded"]??false;def.viewScale=(float?)source["cfg"]["viewScale"]??1;if(source["cfg"]["hip"]?["p"]!=null)def.hip=V(source["cfg"]["hip"]["p"]);EditorUtility.SetDirty(def);count++;File.WriteAllText("Logs/WeaponImport.txt",count+" / "+data["weapons"].Count()+" "+id+" "+triangles+" triangles");}
 AssetDatabase.SaveAssets();return "Imported "+count+" native weapon prefabs and definitions";}
}

